static inline int16_t gpsp_audio_convert_sample(int16_t sample)
{
    int32_t value = sample;
    const int16_t *curve = value < 0 ? gpsp_audio_negative : gpsp_audio_positive;
    uint32_t magnitude = (uint32_t)(value < 0 ? -value : value);
    if (magnitude >= 6144) return curve[384];
    uint32_t index = magnitude >> 4;
    int32_t fraction = (int32_t)(magnitude & 15);
    int32_t a = curve[index];
    int32_t delta = (int32_t)curve[index + 1] - a;
    return (int16_t)(a + ((delta * fraction + 8) >> 4));
}
